package entry

import (
	"strings"

	"github.com/TrebuchetDynamics/gormes-agent/internal/gateway/directory/model/policy"
)

// Entry describes one platform target that can be selected by exact ID, human
// display name, guild-qualified name, or type/display lookup.
type Entry struct {
	ID        string `json:"id"`
	Name      string `json:"name"`
	Type      string `json:"type,omitempty"`
	Guild     string `json:"guild,omitempty"`
	ChatID    string `json:"chat_id,omitempty"`
	ThreadID  string `json:"thread_id,omitempty"`
	ChatTopic string `json:"chat_topic,omitempty"`
}

// Evidence carries user-safe degraded-mode evidence without leaking local state paths.
type Evidence struct {
	Code     string
	Platform string
	Query    string
}

// NormalizePlatform returns the canonical platform key used by directory stores,
// refresh merges, and channel lookups.
func NormalizePlatform(platform string) string {
	return strings.ToLower(policy.TrimText(platform))
}

// NormalizeEntry trims persisted target fields before merge and lookup.
func NormalizeEntry(entry Entry) Entry {
	entry.ID = policy.TrimText(entry.ID)
	entry.Name = policy.TrimText(entry.Name)
	entry.Type = policy.TrimText(entry.Type)
	entry.Guild = policy.TrimText(entry.Guild)
	entry.ChatID = policy.TrimText(entry.ChatID)
	entry.ThreadID = policy.TrimText(entry.ThreadID)
	entry.ChatTopic = policy.TrimText(entry.ChatTopic)
	return entry
}

// NormalizeQuery returns the canonical form used for human channel lookups.
func NormalizeQuery(value string) string {
	return strings.ToLower(trimLeadingChannelMarker(policy.TrimText(value)))
}

func trimLeadingChannelMarker(value string) string {
	return policy.TrimText(strings.TrimLeft(value, "#"))
}

// UpsertEntry replaces an existing entry with the same normalized ID or appends
// it when no cached target exists yet.
func UpsertEntry(entries []Entry, entry Entry) []Entry {
	entries, _ = UpsertValidEntry(entries, entry)
	return entries
}

// UpsertValidEntry normalizes and upserts a complete directory entry. It returns
// false without changing entries when the entry lacks the minimum cached-target
// contract used by refresh merges.
func UpsertValidEntry(entries []Entry, item Entry) ([]Entry, bool) {
	return policy.UpsertByNormalizedID(entries, item, NormalizeEntry, func(entry Entry) string {
		return entry.ID
	}, func(entry Entry) bool {
		return entry.ID != "" && entry.Name != ""
	})
}

package entry

import "github.com/TrebuchetDynamics/gormes-agent/internal/gateway/directory/model/policy"

// TargetDisplayName returns the user-facing selector text for a directory entry.
// It is shared by target resolution and model/tool display rendering so both
// surfaces keep the same platform-specific naming policy.
func TargetDisplayName(platform string, item Entry) string {
	platform = NormalizePlatform(platform)
	name := policy.TrimText(item.Name)
	if platform == "discord" && EntryGuild(item) != "" {
		return "#" + name
	}
	if entryType := policy.TrimText(item.Type); platform != "discord" && entryType != "" {
		return name + " (" + entryType + ")"
	}
	return name
}

package entry

import (
	"strings"

	"github.com/TrebuchetDynamics/gormes-agent/internal/gateway/directory/model/policy"
)

// EntryGuild returns the normalized display guild/server name carried by an
// entry. It is the shared guild identity contract for Discord display grouping
// and guild-qualified target resolution.
func EntryGuild(entry Entry) string {
	return policy.TrimText(entry.Guild)
}

// NormalizeGuildQuery returns the canonical guild/server key used when matching
// user-provided guild-qualified channel selectors.
func NormalizeGuildQuery(value string) string {
	return strings.ToLower(policy.TrimText(value))
}

package entry

import "sort"

// SortEntriesByNameID orders entries by the stable display identity used by
// refresh persistence and grouped display rendering.
func SortEntriesByNameID(entries []Entry) {
	sort.SliceStable(entries, func(i, j int) bool {
		if entries[i].Name != entries[j].Name {
			return entries[i].Name < entries[j].Name
		}
		return entries[i].ID < entries[j].ID
	})
}

package entry

import "testing"

func TestNormalizeQueryTrimsBeforeChannelMarker(t *testing.T) {
	for raw, want := range map[string]string{
		"#General":   "general",
		" #General ": "general",
		"General":    "general",
	} {
		if got := NormalizeQuery(raw); got != want {
			t.Fatalf("NormalizeQuery(%q) = %q, want %q", raw, got, want)
		}
	}
}

func TestUpsertValidEntryNormalizesAndSkipsIncompleteEntries(t *testing.T) {
	entries, ok := UpsertValidEntry(nil, Entry{ID: " 123 ", Name: " Ops ", Type: " group "})
	if !ok {
		t.Fatalf("UpsertValidEntry ok = false, want true")
	}
	if len(entries) != 1 || entries[0].ID != "123" || entries[0].Name != "Ops" || entries[0].Type != "group" {
		t.Fatalf("entries = %+v, want normalized inserted entry", entries)
	}

	entries, ok = UpsertValidEntry(entries, Entry{ID: "123", Name: "Ops Renamed"})
	if !ok {
		t.Fatalf("UpsertValidEntry replacement ok = false, want true")
	}
	if len(entries) != 1 || entries[0].Name != "Ops Renamed" {
		t.Fatalf("entries = %+v, want replacement by ID", entries)
	}

	entries, ok = UpsertValidEntry(entries, Entry{ID: "456"})
	if ok {
		t.Fatalf("UpsertValidEntry incomplete ok = true, want false")
	}
	if len(entries) != 1 || entries[0].ID != "123" {
		t.Fatalf("entries = %+v, want unchanged entries after incomplete entry", entries)
	}
}

package entry

import "testing"

func TestTargetDisplayNameSharesPlatformNamingPolicy(t *testing.T) {
	tests := []struct {
		name     string
		platform string
		entry    Entry
		want     string
	}{
		{name: "discord guild channel", platform: " Discord ", entry: Entry{Name: " general ", Guild: " Sages ", Type: "channel"}, want: "#general"},
		{name: "non discord typed target", platform: "telegram", entry: Entry{Name: " Alice ", Type: " dm "}, want: "Alice (dm)"},
		{name: "plain target", platform: "slack", entry: Entry{Name: " ops "}, want: "ops"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := TargetDisplayName(tt.platform, tt.entry); got != tt.want {
				t.Fatalf("TargetDisplayName() = %q, want %q", got, tt.want)
			}
		})
	}
}

package entry

import "testing"

func TestEntryGuildAndNormalizeGuildQueryShareDiscordGuildIdentity(t *testing.T) {
	entry := Entry{Guild: " Sages "}
	if got := EntryGuild(entry); got != "Sages" {
		t.Fatalf("EntryGuild = %q, want trimmed display guild", got)
	}
	if got := NormalizeGuildQuery(" SAGES "); got != "sages" {
		t.Fatalf("NormalizeGuildQuery = %q, want lowercase trimmed match key", got)
	}
}

